import Vue from 'vue'
import VueRouter from 'vue-router'
import store from '../store'

Vue.use(VueRouter)

const routes = [
  {
    path: '/login',
    name: 'Login',
    component: () => import('@/views/Login.vue'),
    meta: { requiresAuth: false }
  },
  {
    path: '/',
    component: () => import('@/layout/MainLayout.vue'),
    redirect: '/dashboard',
    meta: { requiresAuth: true },
    children: [
      {
        path: 'dashboard',
        name: 'Dashboard',
        component: () => import('@/views/Dashboard.vue')
      },
      {
        path: 'activity',
        name: 'Activity',
        component: () => import('@/views/activity/ActivityList.vue'),
        meta: { roles: ['管理员', '发布者'] }
      },
      {
        path: 'activity/add',
        name: 'ActivityAdd',
        component: () => import('@/views/activity/ActivityForm.vue'),
        meta: { roles: ['管理员', '发布者'] }
      },
      {
        path: 'activity/edit/:id',
        name: 'ActivityEdit',
        component: () => import('@/views/activity/ActivityForm.vue'),
        meta: { roles: ['管理员', '发布者'] }
      },
      {
        path: 'user',
        name: 'User',
        component: () => import('@/views/user/UserList.vue'),
        meta: { roles: ['管理员'] }
      },
      {
        path: 'log',
        name: 'Log',
        component: () => import('@/views/log/LogList.vue'),
        meta: { roles: ['管理员'] }
      },
      // 发布者路由
      {
        path: 'publisher/audit',
        name: 'RegistrationAudit',
        component: () => import('@/views/publisher/RegistrationAudit.vue'),
        meta: { roles: ['发布者', '管理员'] }
      },
      {
        path: 'publisher/statistics',
        name: 'ActivityStatistics',
        component: () => import('@/views/publisher/ActivityStatistics.vue'),
        meta: { roles: ['发布者', '管理员'] }
      },
      // 学生路由
      {
        path: 'student/browse',
        name: 'ActivityBrowse',
        component: () => import('@/views/student/ActivityBrowse.vue'),
        meta: { roles: ['学生'] }
      },
      {
        path: 'student/registration',
        name: 'MyRegistration',
        component: () => import('@/views/student/MyRegistration.vue'),
        meta: { roles: ['学生'] }
      },
      {
        path: 'student/signscore',
        name: 'MySignScore',
        component: () => import('@/views/student/MySignScore.vue'),
        meta: { roles: ['学生'] }
      }
    ]
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

// 路由守卫
router.beforeEach((to, from, next) => {
  const user = store.state.user
  
  // 未登录且需要认证
  if (to.meta.requiresAuth && !user) {
    next('/login')
    return
  }
  
  // 已登录访问登录页，重定向到首页
  if (to.path === '/login' && user) {
    next('/')
    return
  }
  
  // 角色权限检查
  if (to.meta.roles && user) {
    const userRole = user.role
    if (!to.meta.roles.includes(userRole)) {
      // 无权限，重定向到首页
      next('/')
      return
    }
  }
  
  next()
})

export default router
